function clamp_value(value: int64, cap: int64) returns int64:
    if value < -cap:
        return -cap
    if value > cap:
        return cap
    return value

function bounded_weighted_sum(values: list[int64], cap: int64) returns int64:
    mutable int64 sum = 0
    mutable int64 index = 0
    for value in values:
        sum = sum + clamp_value(value, cap) * (index + 1)
        index = index + 1
    return sum

