function valid_triangle(a: int64, b: int64, c: int64) returns bool:
    if a <= 0 or b <= 0 or c <= 0:
        return false
    return a + b > c and a + c > b and b + c > a

function triangle_kind(a: int64, b: int64, c: int64) returns string:
    if not valid_triangle(a, b, c):
        return "invalid"
    if a == b and b == c:
        return "equilateral"
    if a == b or a == c or b == c:
        return "isosceles"
    return "scalene"

