function signed_gcd(a: int64, b: int64) returns int64:
    mutable int64 x = a
    mutable int64 y = b

    if x < 0:
        x = 0 - x
    if y < 0:
        y = 0 - y

    while y != 0:
        mutable int64 remainder = x modulo y
        x = y
        y = remainder

    return x

